-- Pool's Day v1 — announcements 테스트용 더미 10건.
-- 4가지 유형(신기능/기능 업데이트/정보 업데이트/이벤트) + 최근(7일 이내)/이전 섹션 모두 커버.
-- 운영 전 시드 데이터로 활용. 본 운영 시작 시 삭제하거나 실 데이터로 교체.

