-- ============================================================
-- 0007_schedules.sql
-- ============================================================
-- Pool's Day v1 — schedules 테이블 (자유수영 시간표 게시본).
-- 풀당 1행 (최신 승인본). 사용자 제출은 schedule_submissions에서 관리되고, 운영자가 승인 시 여기에 INSERT/UPDATE.
-- by_day는 JSONB — TS 타입 Schedule.byDay와 1:1 매칭 ({ '월': [{start, end, hours?}, ...], ... }).

create table if not exists public.schedules (
  pool_id          text primary key references public.pools(id) on delete cascade,
  author_nickname  text not null,
  by_day           jsonb not null default '{}'::jsonb,
  updated_at       timestamptz not null default now(),
  approved_at      timestamptz default now()
);

-- updated_at 자동 갱신 (pools와 동일 트리거 함수 재사용)
drop trigger if exists schedules_set_updated_at on public.schedules;
create trigger schedules_set_updated_at
  before update on public.schedules
  for each row execute function public.set_updated_at();

alter table public.schedules enable row level security;

drop policy if exists schedules_read_all on public.schedules;
create policy schedules_read_all on public.schedules
  for select using (true);

-- 시드 데이터 — src/data/dummyPools.ts의 dummySchedules 그대로 이관.
-- 운영자는 Dashboard에서 직접 INSERT/UPDATE/DELETE.
insert into public.schedules (pool_id, author_nickname, by_day, updated_at) values
  ('POOL_SEOUL_0002', '수영맨', $$
    {
      "월": [{"start":"06:00","end":"08:00","hours":2}, {"start":"20:00","end":"21:30","hours":1.5}],
      "화": [{"start":"06:00","end":"08:00","hours":2}],
      "수": [{"start":"06:00","end":"08:00","hours":2}, {"start":"12:00","end":"13:30","hours":1.5}],
      "목": [{"start":"06:00","end":"08:00","hours":2}],
      "금": [{"start":"06:00","end":"08:00","hours":2}],
      "토": [{"start":"08:00","end":"12:00","hours":4}],
      "일": [{"start":"08:00","end":"12:00","hours":4}]
    }
  $$::jsonb, '2026-10-31'::timestamptz),
  ('POOL_SEOUL_0001', '풀러', $$
    {
      "월": [{"start":"05:30","end":"07:30","hours":2}, {"start":"21:00","end":"22:00","hours":1}],
      "화": [{"start":"05:30","end":"07:30","hours":2}],
      "수": [{"start":"05:30","end":"07:30","hours":2}],
      "토": [{"start":"08:00","end":"11:00","hours":3}],
      "일": [{"start":"08:00","end":"11:00","hours":3}]
    }
  $$::jsonb, '2026-11-02'::timestamptz)
on conflict (pool_id) do nothing;

-- pools.has_schedule 자동 동기화 (해당 풀에 시간표 있으면 true)
update public.pools
set has_schedule = true
where id in (select pool_id from public.schedules);


-- ============================================================
-- 0008_submissions.sql
-- ============================================================
-- Pool's Day v1 — 사용자 제출(submissions) 테이블 2종.
-- (a) schedule_submissions: 시간표 작성/수정 요청
-- (b) pool_submissions: 수영장 추가/수정 요청
--
-- 둘 다 RLS:
--   - INSERT: anon/authenticated 모두 허용 (사용자가 제출)
--   - SELECT: 운영자만 (Phase 1엔 v0 권한 모델 없으므로 select는 기본 차단)
-- 운영자는 Supabase Dashboard에서 service_role로 직접 조회/검수.

-- ===== (a) schedule_submissions =====
create table if not exists public.schedule_submissions (
  id              uuid primary key default gen_random_uuid(),
  pool_id         text not null references public.pools(id) on delete cascade,
  nickname        text,                                                          -- NULL = 익명 (ANON_NICKNAME)
  by_day          jsonb not null,                                                -- Schedule.byDay 형태
  status          text not null default 'pending'
                    check (status in ('pending', 'approved', 'rejected')),
  submitter_note  text,                                                          -- 추후 사용자 메모용 옵션
  reviewed_at     timestamptz,
  reviewed_by     text,
  submitted_at    timestamptz not null default now()
);

create index if not exists schedule_submissions_pool_id_idx
  on public.schedule_submissions (pool_id);
create index if not exists schedule_submissions_status_idx
  on public.schedule_submissions (status, submitted_at desc);

alter table public.schedule_submissions enable row level security;

drop policy if exists schedule_submissions_insert_any on public.schedule_submissions;
create policy schedule_submissions_insert_any on public.schedule_submissions
  for insert with check (true);


-- ===== (b) pool_submissions =====
create table if not exists public.pool_submissions (
  id                 uuid primary key default gen_random_uuid(),
  mode               text not null check (mode in ('create', 'edit')),
  pool_id            text references public.pools(id),                           -- edit일 때만 존재
  pool_name          text not null,                                              -- 사용자가 입력한 풀 이름
  description        text,                                                       -- create: 추가 정보 / edit: 수정 요청 본문
  submitter_contact  text,                                                       -- 옵션 — 이메일/연락처
  status             text not null default 'pending'
                       check (status in ('pending', 'approved', 'rejected')),
  reviewed_at        timestamptz,
  reviewed_by        text,
  submitted_at       timestamptz not null default now()
);

create index if not exists pool_submissions_status_idx
  on public.pool_submissions (status, submitted_at desc);

alter table public.pool_submissions enable row level security;

drop policy if exists pool_submissions_insert_any on public.pool_submissions;
create policy pool_submissions_insert_any on public.pool_submissions
  for insert with check (true);


-- ============================================================
-- 0011_pools_truncate.sql
-- ============================================================
-- Pool's Day v1 — pools 전체 비우기.
-- 컨셉 변경: bulk import 폐기, 운영자가 대형 수영장만 수동 등록.
-- schedules / schedule_submissions는 FK cascade로 자동 삭제.
-- pool_submissions(edit mode)는 RESTRICT라 CASCADE 필수.

truncate table public.pools restart identity cascade;


