-- ============================================================
-- Pool's Day v1 — 사당문화회관(POOL_SEOUL_0006) 수심 반영.
-- 0024는 출처 "전화문의 필요"라 수심 컬럼 생략(NULL). 사용자 확인값으로 보정.
-- min == max (수심 차이 없음) → 클라이언트는 "1.2m"로 단일 표시(범위 표기 안 함).
-- 사용자가 Supabase에 직접 입력한 값을 마이그레이션으로 고정(재현성/소스 일치).
-- ※ 값 가정: depth_min = depth_max = 1.2 (m). 실제 다르면 알려주면 수정.
-- 0024 ON CONFLICT DO NOTHING이라 INSERT 재실행 무효 → UPDATE 보정.

update public.pools
set depth_min = 1.2,
    depth_max = 1.2
where id = 'POOL_SEOUL_0006';


-- ============================================================
-- 0029_pool_sadang_schedule_fix.sql
-- ============================================================
-- Pool's Day v1 — 사당문화회관(POOL_SEOUL_0006) 자유수영 시간표 보정.
-- 0024는 cbswim webflow의 뭉뚱그린 표("월~금 13:00~13:50/19:00~19:50")를
--   잘못 해석해 월·수에도 19:00~19:50을 넣었음.
-- 공식 출처(동작구도시관리공단 https://sports.idongjak.or.kr/home/61) 기준 정정:
--   · 13:00~13:50 : 월~금 전부
--   · 19:00~19:50 : 화·목만 (월·수·금은 없음)
--   · 금 19:00~21:50 (저녁 연장, 13:00~13:50 + 이거)
--   · 토 13:00~14:50 / 15:00~16:50
--   · 일 09:00~10:50 / 11:00~12:50 / 13:00~14:50 / 15:00~16:50 (매월 1주차 — day_notes 0024 그대로)
-- 0024 ON CONFLICT (pool_id) DO NOTHING이라 INSERT 재실행 무효 → by_day UPDATE.
-- (day_notes의 "일: 매월 1주차" 안내는 0024에서 이미 정확 → 미변경.)

update public.schedules
set by_day = $${
  "월": [{"start":"13:00","end":"13:50","hours":0.83}],
  "화": [{"start":"13:00","end":"13:50","hours":0.83}, {"start":"19:00","end":"19:50","hours":0.83}],
  "수": [{"start":"13:00","end":"13:50","hours":0.83}],
  "목": [{"start":"13:00","end":"13:50","hours":0.83}, {"start":"19:00","end":"19:50","hours":0.83}],
  "금": [{"start":"13:00","end":"13:50","hours":0.83}, {"start":"19:00","end":"21:50","hours":2.83}],
  "토": [{"start":"13:00","end":"14:50","hours":1.83}, {"start":"15:00","end":"16:50","hours":1.83}],
  "일": [
    {"start":"09:00","end":"10:50","hours":1.83},
    {"start":"11:00","end":"12:50","hours":1.83},
    {"start":"13:00","end":"14:50","hours":1.83},
    {"start":"15:00","end":"16:50","hours":1.83}
  ]
}$$::jsonb
where pool_id = 'POOL_SEOUL_0006';


-- ============================================================
-- 0030_schedules_operator_to_poolsday.sql
-- ============================================================
-- Pool's Day v1 — 운영자 시드 시간표의 작성자 표기를 '운영자' → '풀스데이'.
-- 시간표 마지막 등록자가 운영자(서비스가 공식 등록)인 경우, 사용자 화면엔
--   '운영자님'이 아니라 '풀스데이님'으로 노출되게.
-- 대상: 운영자 시드(0021 관악, 0024/0029 사당) — author_nickname='운영자'.
--   (0014 샘플 시드는 '잠실회원' 등 다른 닉이라 영향 없음.)
-- 코드에 '운영자' 센티넬 의존 없음 — 저장값만 교체하면 ScheduleView가 그대로 표시.
-- 앞으로 운영자가 시드하는 schedules는 처음부터 author_nickname='풀스데이' 사용.

update public.schedules
set author_nickname = '풀스데이'
where author_nickname = '운영자';


