    '서울특별시 영등포구 국회대로 615',
    37.5266924, 126.9027314, 'indoor', 'public',
    '02-2630-2913', 'https://spc2.y-sisul.or.kr/page/center/center.03.asp',
    6, 25, 1.2, 1.2,
    '{}', false, false, false,
    true, true,
    3000, 3000, 4500,
    'https://__NEW_PROJECT_REF__.supabase.co/storage/v1/object/public/pool-photos/POOL_SEOUL_0007.jpg')
