-- ============================================================
-- 0032_schedule_daynote_tone.sql
-- ============================================================
-- Pool's Day v1 — 요일 안내문구(day_notes) 톤앤매너 통일.
-- 표준 톤(사당 0024 기준): "매월 {주차}주차에만 운영합니다." — 숫자 주차, "에만 운영합니다." 종결.
-- 영등포제2스포츠센터(0031) "매월 둘째·넷째 일요일만 개관합니다." → 표준 톤으로 정정.
--   (둘째·넷째 = 2·4주차) 0031 ON CONFLICT라 INSERT 재실행 무효 → day_notes UPDATE.
-- 참고: 사당(POOL_SEOUL_0006) "매월 1주차에만 운영합니다."는 이미 표준 톤 → 미변경.

update public.schedules
set day_notes = $${"일":"매월 2·4주차에만 운영합니다."}$$::jsonb
where pool_id = 'POOL_SEOUL_0007';


-- ============================================================
-- 0033_schedule_daynote_tone_fix.sql
-- ============================================================
-- Pool's Day v1 — 요일 안내문구 톤 표준 확정 + 사당/영등포 정규화.
-- 표준(사용자 확정 2026-05-16): "매월 {주차} 일요일에만 운영합니다."
--   · 단일:  "매월 1주차 일요일에만 운영합니다."
--   · 복수:  "매월 2, 4주차 일요일에만 운영합니다." (주차는 쉼표, 요일어 '일요일' 포함)
-- 경위: 사당(0024) 원문은 "매월 1주차에만 운영합니다."였고, 사용자가 Supabase에서
--   "매월 1주차 일요일에만 운영합니다."로 직접 수정 → 마이그레이션을 그 값으로 동기화
--   (source of truth 일치, 재현성). 영등포(0032)의 "매월 2·4주차에만 운영합니다."도 표준으로.
-- 0024/0031/0032가 ON CONFLICT라 INSERT 재실행 무효 → day_notes UPDATE로 정정.
-- (멱등: 사당 행은 사용자 수동값과 동일해져 변화 없음.)

update public.schedules
set day_notes = $${"일":"매월 1주차 일요일에만 운영합니다."}$$::jsonb
where pool_id = 'POOL_SEOUL_0006';

update public.schedules
set day_notes = $${"일":"매월 2, 4주차 일요일에만 운영합니다."}$$::jsonb
where pool_id = 'POOL_SEOUL_0007';


-- ============================================================
-- 0034_pool_kbs_sportsworld.sql
-- ============================================================
-- Pool's Day v1 — 수영장 1곳 추가: KBS스포츠월드 (POOL_SEOUL_0008).
-- 출처: cbswim webflow. ※ 공식(kbssw.co.kr)은 SSL 인증서 오류로 fetch 검증 실패 —
--   시간표는 cbswim 단독(공식 교차검증 못 함). 추후 공식 확인되면 UPDATE 보정 가능.
-- 좌표 [신뢰도 높음]: 카카오 Local API 도로명주소 정확 매치 "서울 강서구 공항대로 376"
--   (ROAD_ADDR). 좌표 선확보 → INSERT에 직접 박음(단일 마이그레이션, 보정 없음).
-- 수심 1.2~1.8 (사용자 확인 — cbswim 미기재라 질문해서 받음, min≠max → 화면 "1.2~1.8m").
-- ownership=private: KBS비즈(주) 운영 민간 시설(요금 8천/9천대). 가격 성인 평일/주말(쉼표 없는 정수).
-- 작성자 '풀스데이'. photo_url 신규 풀이라 INSERT에 직접 박음(pool-photos/POOL_SEOUL_0008.jpg 업로드 필요).

insert into public.pools (
  id, name, region, district, address, lat, lng, type, ownership,
  phone, website, lane_count, pool_length, depth_min, depth_max,
