-- 자유수영 시간표 (cbswim 기준, 공식 미검증)
--   평일(월~금) 13:30~15:30 / 토·일 09:00~17:00
--   일요일은 매월 2·4주 휴장 → 1·3·5주만 운영(day_note, 표준 톤).
--   hours = 시간(2h, 8h).
insert into public.schedules (pool_id, author_nickname, by_day, day_notes, updated_at) values
  ('POOL_SEOUL_0008', '풀스데이', $${
    "월": [{"start":"13:30","end":"15:30","hours":2}],
    "화": [{"start":"13:30","end":"15:30","hours":2}],
    "수": [{"start":"13:30","end":"15:30","hours":2}],
    "목": [{"start":"13:30","end":"15:30","hours":2}],
    "금": [{"start":"13:30","end":"15:30","hours":2}],
    "토": [{"start":"09:00","end":"17:00","hours":8}],
    "일": [{"start":"09:00","end":"17:00","hours":8}]
  }$$::jsonb, $${"일":"매월 1, 3, 5주차 일요일에만 운영합니다."}$$::jsonb, '2026-05-16'::timestamptz)
on conflict (pool_id) do nothing;

-- has_schedule 동기화 (안전)
update public.pools
set has_schedule = true
where id = 'POOL_SEOUL_0008'
  and exists (select 1 from public.schedules where pool_id = 'POOL_SEOUL_0008');


-- ============================================================
-- 0035_schedules_slot_groups.sql
-- ============================================================
-- Pool's Day v1 — 자유수영 시간표에 계절/변형 운영(슬롯 그룹) 지원.
-- 일부 풀(예: KBS스포츠월드)은 하절기(6~9월) 등 시즌별로 운영시간이 다름.
-- Figma 144:3716 — 요일 슬롯을 라벨 붙은 그룹으로 분할 표시
--   (예: "기본 운영 (매월 2,4주차 일요일은 쉽니다.)" / "6~9월 운영 (하절기는 휴장일이 없습니다.)").
--
-- 모델(하위호환·추가형): 기존 by_day(flat)는 그대로 두고 slot_groups(옵션) 추가.
--   구조: { "<요일>": [ { "label": "<그룹 캡션>", "slots": [ {start,end,hours}, ... ] }, ... ] }
--   slot_groups[요일] 있으면 ScheduleView가 그룹 렌더, 없으면 by_day flat 그대로.
--   by_day는 여전히 "해당 요일 운영 여부"(요일칩 활성)·dayNote 게이팅의 기준 →
--   그룹 풀도 by_day[요일]에 대표(기본) 슬롯을 채워둔다.
-- 기존 30+ 풀 영향 없음(slot_groups NULL/{} → flat 동작 유지).

alter table public.schedules
  add column if not exists slot_groups jsonb default '{}'::jsonb;


-- ============================================================
-- 0036_pool_kbs_schedule_seasonal.sql
-- ============================================================
-- Pool's Day v1 — KBS스포츠월드(POOL_SEOUL_0008) 시간표 공식 정정 + 하절기 그룹.
-- 출처: 공식 kbssw.co.kr (WebFetch는 SSL 체인 오류 → curl -k 로 취득; 페이지 인코딩
--   깨졌으나 시각은 ASCII라 신뢰 가능 + Figma 144:3716의 하절기 수치와 정확 일치 = 교차검증).
-- 0034는 cbswim 기준(토·일 09:00~17:00 단일)이라 정정. 0034 ON CONFLICT → UPDATE.
--
-- 공식 자유수영:
--   · 평일(월~금) 13:30~15:30 (시즌 변동 없음 → flat, slot_groups 없음)
--   · 토·일 기본: 1부 09:00~12:30, 2부 13:30~17:00
--   · 하절기(6~9월): 1부 09:00~11:30, 2부 12:30~15:00, 3부 16:00~18:30
--   · 일요일 정기휴무: 매월 2·4째 일요일 (하절기는 휴장 없음) / 토요일 휴무 없음
-- 일요일 휴무 안내는 slot_groups의 '기본 운영' 라벨로 표기(Figma 144:3716) →
--   기존 day_notes(일)와 중복/모순 방지 위해 day_notes 비움.
-- by_day는 기본(레거시·요일칩·게이팅 기준) 유지, slot_groups는 토·일만(시즌 변동 있는 요일).

update public.schedules
set by_day = $${
  "월": [{"start":"13:30","end":"15:30","hours":2}],
  "화": [{"start":"13:30","end":"15:30","hours":2}],
  "수": [{"start":"13:30","end":"15:30","hours":2}],
  "목": [{"start":"13:30","end":"15:30","hours":2}],
  "금": [{"start":"13:30","end":"15:30","hours":2}],
  "토": [{"start":"09:00","end":"12:30","hours":3.5}, {"start":"13:30","end":"17:00","hours":3.5}],
  "일": [{"start":"09:00","end":"12:30","hours":3.5}, {"start":"13:30","end":"17:00","hours":3.5}]
}$$::jsonb,
    slot_groups = $${
  "토": [
    {"label":"기본 운영", "slots":[
      {"start":"09:00","end":"12:30","hours":3.5},
      {"start":"13:30","end":"17:00","hours":3.5}
    ]},
    {"label":"6~9월 운영 (하절기는 휴장일이 없습니다.)", "slots":[
      {"start":"09:00","end":"11:30","hours":2.5},
      {"start":"12:30","end":"15:00","hours":2.5},
      {"start":"16:00","end":"18:30","hours":2.5}
    ]}
  ],
  "일": [
    {"label":"기본 운영 (매월 2, 4주차 일요일은 쉽니다.)", "slots":[
      {"start":"09:00","end":"12:30","hours":3.5},
      {"start":"13:30","end":"17:00","hours":3.5}
    ]},
    {"label":"6~9월 운영 (하절기는 휴장일이 없습니다.)", "slots":[
      {"start":"09:00","end":"11:30","hours":2.5},
      {"start":"12:30","end":"15:00","hours":2.5},
      {"start":"16:00","end":"18:30","hours":2.5}
    ]}
  ]
}$$::jsonb,
    day_notes = '{}'::jsonb
where pool_id = 'POOL_SEOUL_0008';


-- ============================================================
-- 0037_pool_kbs_schedule_label_fix.sql
-- ============================================================
-- Pool's Day v1 — KBS스포츠월드(POOL_SEOUL_0008) slot_groups 라벨 문구 정정.
-- 사용자 제공 화면(렌더 이미지) 기준 문구 통일:
--   · 일: "기본 운영 (매월 2, 4주차 일요일은 쉽니다.)"
--         "6~9월 운영 (하절기는 매주 일요일 운영합니다.)"  ← 0036의 "휴장일이 없습니다" 정정
--   · 토: "기본 운영" / "6~9월 운영" (토요일은 휴무 규칙 없음 → 부가설명 없이 간결)
-- 시각(slots)·by_day·day_notes는 0036 그대로, 라벨 텍스트만 변경.
-- 0036 이미 적용됐을 수 있어 UPDATE로 멱등 정정.

update public.schedules
set slot_groups = $${
  "토": [
    {"label":"기본 운영", "slots":[
      {"start":"09:00","end":"12:30","hours":3.5},
      {"start":"13:30","end":"17:00","hours":3.5}
    ]},
    {"label":"6~9월 운영", "slots":[
      {"start":"09:00","end":"11:30","hours":2.5},
      {"start":"12:30","end":"15:00","hours":2.5},
      {"start":"16:00","end":"18:30","hours":2.5}
    ]}
  ],
  "일": [
    {"label":"기본 운영 (매월 2, 4주차 일요일은 쉽니다.)", "slots":[
      {"start":"09:00","end":"12:30","hours":3.5},
      {"start":"13:30","end":"17:00","hours":3.5}
    ]},
    {"label":"6~9월 운영 (하절기는 매주 일요일 운영합니다.)", "slots":[
      {"start":"09:00","end":"11:30","hours":2.5},
      {"start":"12:30","end":"15:00","hours":2.5},
      {"start":"16:00","end":"18:30","hours":2.5}
    ]}
  ]
}$$::jsonb
where pool_id = 'POOL_SEOUL_0008';


-- ============================================================
-- 0038_pool_kbs_slot_groups_months.sql
-- ============================================================
-- Pool's Day v1 — KBS스포츠월드(POOL_SEOUL_0008) slot_groups에 months 추가.
-- 시간표 타임 더블탭 → 일정 등록 플로우가 "그 날짜가 몇 월이냐"로 시즌 그룹을
-- 골라 타임표를 보여주려면, 각 그룹이 어느 달에 적용되는지 구조적 데이터 필요.
--   · 기본 운영   → 1~5, 10~12월 (비하절기)
--   · 6~9월 운영  → 6, 7, 8, 9월 (하절기)
-- 라벨·시각·by_day·day_notes는 0037 그대로, 그룹에 "months" 키만 추가. 멱등 UPDATE.

update public.schedules
set slot_groups = $${
  "토": [
    {"label":"기본 운영", "months":[1,2,3,4,5,10,11,12], "slots":[
      {"start":"09:00","end":"12:30","hours":3.5},
      {"start":"13:30","end":"17:00","hours":3.5}
    ]},
    {"label":"6~9월 운영", "months":[6,7,8,9], "slots":[
      {"start":"09:00","end":"11:30","hours":2.5},
      {"start":"12:30","end":"15:00","hours":2.5},
      {"start":"16:00","end":"18:30","hours":2.5}
    ]}
  ],
  "일": [
    {"label":"기본 운영 (매월 2, 4주차 일요일은 쉽니다.)", "months":[1,2,3,4,5,10,11,12], "slots":[
      {"start":"09:00","end":"12:30","hours":3.5},
      {"start":"13:30","end":"17:00","hours":3.5}
    ]},
    {"label":"6~9월 운영 (하절기는 매주 일요일 운영합니다.)", "months":[6,7,8,9], "slots":[
      {"start":"09:00","end":"11:30","hours":2.5},
      {"start":"12:30","end":"15:00","hours":2.5},
      {"start":"16:00","end":"18:30","hours":2.5}
    ]}
  ]
}$$::jsonb
where pool_id = 'POOL_SEOUL_0008';


-- ============================================================
-- 0039_pool_yeongdeungpo2_daynote_resync.sql
-- ============================================================
-- Pool's Day v1 — 영등포제2스포츠센터(POOL_SEOUL_0007) 일요일 안내문구 재동기화.
-- 표준(사용자 확정 2026-05-16): "매월 {주차} 일요일에만 운영합니다."
--   복수 주차는 쉼표(2, 4), 가운뎃점 금지, 요일어('일요일') 포함.
-- 0033에서 이미 표준값으로 정정했으나 DB 미반영 상태 → 본 마이그레이션으로 재설정.
-- 다른 요일 안내문구가 추가돼도 안 깨지게 "일" 키만 jsonb 병합(||)으로 갱신. 멱등.
-- 전제: by_day["일"]에 슬롯 1개 이상(0031 INSERT에서 일요일 슬롯 존재) → 제약 충족.

update public.schedules
set day_notes =
  coalesce(day_notes, '{}'::jsonb)
  || $${"일":"매월 2, 4주차 일요일에만 운영합니다."}$$::jsonb
where pool_id = 'POOL_SEOUL_0007';


-- ============================================================
-- 0040_pool_kbs_price_fix.sql
-- ============================================================
-- Pool's Day v1 — KBS스포츠월드(POOL_SEOUL_0008) 이용요금 공식 정정.
-- 출처: 사용자 제공 공식 요금(kbssw.co.kr 기준).
--   · 평일 성인 9,000원  → price_weekday
--   · 주말 성인 10,000원 → price_weekend
--   (청소년 9,000·어린이 8,000 등은 스키마 컬럼 없음 → 성인 기준만 저장)
-- 0034가 cbswim 추정치(8000/9000)로 박았고 ON CONFLICT DO NOTHING이라
-- INSERT 재실행 무효 → UPDATE로 정정. 멱등.
-- price_per_session(레거시 단일 표시용)도 stale 8000 제거 위해 평일가 9000으로 동기화.

update public.pools
set price_weekday     = 9000,
    price_weekend     = 10000,
    price_per_session = 9000
where id = 'POOL_SEOUL_0008';


-- ============================================================
-- 0041_pool_kbs_has_kids_pool.sql
-- ============================================================
-- Pool's Day v1 — KBS스포츠월드(POOL_SEOUL_0008) 유아풀 보유 정정.
-- 출처: 사용자 확인(KBS에 유아풀 있음). 0034가 has_kids_pool=false로 박았고
-- ON CONFLICT (id) DO NOTHING이라 INSERT 재실행 무효 → UPDATE로 정정. 멱등.
-- (0027 관악구민종합체육센터 유아풀 정정과 동일 패턴.)

update public.pools
set has_kids_pool = true
where id = 'POOL_SEOUL_0008';


-- ============================================================
-- 0042_notifications.sql
-- ============================================================
-- Pool's Day v1 — 메시지(알림) 발송 이력.
--
-- 발송 Rule은 코드 레지스트리(src/lib/messages/rules.ts)에서 관리하고,
-- 액션 발생 시 클라이언트(dispatchMessage)가 이 테이블에 직접 insert 한다.
-- 프로필 본체가 아직 로컬(AsyncStorage)이라 수신자 식별은
-- 친구 추가용 계정 ID(profile.id) = user_code 로 한다.
--
-- Phase 1 한계: 지금은 "그 액션을 한 로컬 사용자 본인"의 이력 행만 적재된다
-- (상대방에게 가는 행은 실 인증/서버 사이드 디스패치 = Phase 2).
--
-- RLS (mock-auth 단계 — submissions/profile_nicknames 와 동일 톤):
--   - INSERT: anon/authenticated 모두 허용 (사용자 클라이언트가 적재)
--   - SELECT: user_code 를 알면 누구나 (민감정보 미저장 — title/본문 텍스트만).
--     실 Supabase Auth(auth.uid) 연동 후 본인 행만 보도록 강화 예정.

create table if not exists public.notifications (
  id          uuid primary key default gen_random_uuid(),
  user_code   text not null,                          -- 수신자 = profile.id(친구 코드)
  kind        text not null,                          -- MessageKind (rules.ts)
  title       text not null,
  body        jsonb not null default '[]'::jsonb,     -- 본문 줄 배열 string[]
  params      jsonb not null default '{}'::jsonb,     -- 템플릿 파라미터 원본
  actions     jsonb not null default '[]'::jsonb,     -- 표시용 액션 ['거절','수락'...]
  related     jsonb not null default '{}'::jsonb,     -- poolId/date 등 부가 정보
  read        boolean not null default false,
  created_at  timestamptz not null default now()
);

create index if not exists notifications_user_code_idx
  on public.notifications (user_code, created_at desc);

alter table public.notifications enable row level security;

drop policy if exists notifications_select_any on public.notifications;
create policy notifications_select_any on public.notifications
  for select using (true);

drop policy if exists notifications_insert_any on public.notifications;
create policy notifications_insert_any on public.notifications
  for insert with check (true);


-- ============================================================
-- 0043_nickname_policy.sql
-- ============================================================
-- Pool's Day — 닉네임 정책 서버측 강제 (운영 사칭 / 욕설 차단).
--
-- 클라이언트(lib/nicknames.nicknameBlockReason)는 즉시 UX 피드백용 1차 필터.
-- 최종 권위·우회 불가 방어선은 여기: profile_nicknames INSERT 시 트리거가
-- 차단어 포함 닉네임을 거부한다. 차단어는 데이터 테이블로 관리(운영자가
-- service_role로 추가/삭제 — 코드 배포 없이 정책 갱신).

-- 차단어 레지스트리
create table if not exists public.nickname_blocklist (
  term       text primary key,
  kind       text not null check (kind in ('reserved', 'profanity')),
  created_at timestamptz not null default now()
);

alter table public.nickname_blocklist enable row level security;

-- 조회는 공개 허용(클라가 목록 동기화에 쓸 수 있게). 변경은 정책 미정의
-- → service_role(운영)만 insert/update/delete 가능.
drop policy if exists nickname_blocklist_select_any on public.nickname_blocklist;
create policy nickname_blocklist_select_any on public.nickname_blocklist
  for select using (true);

